SELECT , c.course_name AS courseName, c.course_code AS courseCode, tu.real_name AS teacherName, cr.room_no AS roomNo, cr.building AS building FROM course_schedule cs LEFT JOIN course c ON c.id = cs.course_id AND c.deleted = 0 LEFT JOIN teacher t ON t.id = c.teacher_id AND t.deleted = 0 LEFT JOIN sys_user tu ON tu.id = t.user_id AND tu.deleted = 0 LEFT JOIN classroom cr ON cr.id = cs.classroom_id AND cr.deleted = 0 WHERE cs.deleted = 0 AND cs.course_id IN
#{id}
AND cs.semester_id = #{semesterId}
ORDER BY cs.day_of_week, cs.start_section

SELECT COUNT(*)
FROM course_schedule cs
INNER JOIN course c ON c.id = cs.course_id AND c.deleted = 0
WHERE cs.deleted = 0
AND cs.semester_id = #{semesterId}
AND c.teacher_id = #{teacherId}
AND cs.day_of_week = #{dayOfWeek}
AND cs.start_section <= #{endSection}
AND cs.end_section >= #{startSection}
AND cs.start_week <= #{endWeek}
AND cs.end_week >= #{startWeek}

    AND c.id != #{excludeCourseId}

SELECT COUNT(*)
FROM course_schedule cs
WHERE cs.deleted = 0
AND cs.semester_id = #{semesterId}
AND cs.classroom_id = #{classroomId}
AND cs.day_of_week = #{dayOfWeek}
AND cs.start_section <= #{endSection}
AND cs.end_section >= #{startSection}
AND cs.start_week <= #{endWeek}
AND cs.end_week >= #{startWeek}

    AND cs.course_id != #{excludeCourseId}
